script:
/* Главная нового агента: «Начало работы» из фактов store, скрытие, анимация завершения, события, тур. */
class Component extends DCLogic {
  constructor(props) {
    super(props);
    this.state = { help: false, qr: false, why: false, toast: '', video: false, vPlay: false, vPct: 0, cel: 0 };
  }
  componentDidMount() { this.checkCeleb(); }
  componentDidUpdate() { this.checkCeleb(); }
  componentWillUnmount() { clearTimeout(this._t); clearInterval(this._vi); (this._cs || []).forEach(clearTimeout); }
  /* все шаги выполнены или отмечены «Не нужно»: один раз проигрываем завершение и запоминаем, что обучение закончено */
  checkCeleb() {
    if (this.state.cel || HB.store.get('onb.done') || !HB.onb.allDone()) return;
    HB.store.set('onb.done', true);
    const reduce = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches);
    const at = (ms, o) => this._cs.push(setTimeout(() => this.setState(o), ms));
    this._cs = [];
    this.setState({ cel: reduce ? 2 : 1, video: false });
    this._cs.push(setTimeout(() => { const bl = document.getElementById('nb-block'); if (bl && bl.scrollIntoView) bl.scrollIntoView({ block: 'center' }); }, 60));
    if (reduce) { at(2000, { cel: 0 }); } else { at(900, { cel: 2 }); at(3000, { cel: 3 }); at(3700, { cel: 0 }); }
  }
  say(t) { this.setState({ toast: t }); clearTimeout(this._t); this._t = setTimeout(() => this.setState({ toast: '' }), 3200); }
  markTour(msg) { HB.store.set('facts.tourSeen', true); this.setState({ vPlay: false, vPct: 100 }); clearInterval(this._vi); if (msg) this.say(msg); }
  closeVideo() { clearInterval(this._vi); this.setState({ video: false, vPlay: false, vPct: HB.store.get('facts.tourSeen') ? 100 : 0 }); setTimeout(() => { const c = document.getElementById('nv-card'); if (c) c.focus(); }, 60); }
  renderVals() {
    const S = this.state, set = (o) => this.setState(o), store = HB.store;
    const toast = (t) => this.say(t);
    const seen = !!store.get('facts.tourSeen');
    const steps = HB.onb.steps(), total = HB.onb.total, n = HB.onb.count();
    const done = !!store.get('onb.done'), hidden = !!store.get('onb.hidden'), cel = S.cel;
    const show = cel > 0 || (!done && !hidden);
    const nx = steps.filter((s) => s.cur)[0] || steps[steps.length - 1];
    const rows = steps.map((s) => ({
      n: s.n, t: s.t, cls: (s.state === 'done' ? 'is-done' : s.state === 'skip' ? 'is-skip' : '') + (s.cur ? ' is-cur' : ''),
      aria: s.cur ? 'step' : 'false', isDone: s.state === 'done', isSkip: s.state === 'skip', isNum: s.state === 'todo',
      link: !!s.href && s.state === 'todo', tour: s.act === 'tour' && s.state === 'todo', plain: s.state !== 'todo' || (!s.href && s.act !== 'tour'), href: s.href || '',
      cur: !!s.cur && s.state === 'todo', tag: s.req ? '' : (s.state === 'skip' ? 'отмечено «Не нужно»' : 'необязательно'), hasTag: !s.req,
      canSkip: !s.req && s.state === 'todo', skipLabel: 'Не нужно: ' + s.t.charAt(0).toLowerCase() + s.t.slice(1),
      skip: () => { const k = Object.assign({}, store.get('onb.skipped')); k[s.skip] = true; store.set('onb.skipped', k); set({}); },
      canBack: s.state === 'skip', backLabel: 'Вернуть шаг: ' + s.t.charAt(0).toLowerCase() + s.t.slice(1),
      back: () => { const k = Object.assign({}, store.get('onb.skipped')); k[s.skip] = false; store.set('onb.skipped', k); set({}); }
    }));
    const next = { t: nx.t, d: nx.d || '', btn: nx.btn || '', href: nx.href || '', isLink: !!nx.href, isTour: nx.act === 'tour', label: n >= total ? 'Всё готово' : 'Следующий шаг',
      icUser: nx.ic === 'user', icFile: nx.ic === 'file', icSend: nx.ic === 'send', icPlay: nx.ic === 'play', icUsers: nx.ic === 'users' };
    const ev = HB.events();
    const gone = (e) => { if (e && e.key === 'Escape') this.closeVideo(); };
    return {
      help: S.help, toggleHelp: () => set({ help: !S.help }),
      qr: S.qr, openQr: () => set({ qr: true }), closeQr: () => set({ qr: false }), saveQr: () => { set({ qr: false }); toast('Картинка сохранена в загрузки'); },
      why: S.why, notWhy: !S.why, whyExp: S.why ? 'true' : 'false', whyBtn: S.why ? 'Свернуть' : 'Как это работает', toggleWhy: () => set({ why: !S.why }),
      copyLink: () => toast('Ссылка скопирована'),
      shareWa: () => toast('В кабинете откроется WhatsApp со ссылкой'),
      shareTg: () => toast('В кабинете откроется Telegram со ссылкой'),
      shareMl: () => toast('В кабинете откроется письмо со ссылкой'),
      asClient: () => toast('В кабинете откроется страница так, как её увидит клиент'),
      vOn: S.video, openVideo: () => { set({ video: true, vPct: seen ? 100 : S.vPct }); setTimeout(() => { const x = document.getElementById('nv-x'); if (x) x.focus(); }, 60); },
      vClose: () => this.closeVideo(), vScrim: () => this.closeVideo(), vStop: (e) => { e.stopPropagation(); }, vKey: gone,
      vPlayBtn: () => {
        if (S.vPlay || seen) return;
        set({ vPlay: true, vPct: 0 });
        clearInterval(this._vi);
        this._vi = setInterval(() => { const p = Math.min(100, this.state.vPct + 10); if (p >= 100) { this.markTour('Тур просмотрен до конца'); } else this.setState({ vPct: p }); }, 350);
      },
      vSeen: () => { this.markTour('Тур отмечен как просмотренный'); },
      vPlaying: S.vPlay, vPctS: seen ? 100 : S.vPct, vSeenNow: seen, vNotSeen: !seen, vPlayLabel: S.vPlay ? 'Идёт показ…' : 'Смотреть тур',
      learn: show, notLearn: !show,
      showStrip: !done && hidden && cel === 0,
      hide: () => { store.set('onb.hidden', true); toast('Начало работы скрыто. Вернуть можно кнопкой «Показать снова» на этой странице'); },
      show: () => { store.set('onb.hidden', false); set({}); },
      cntT: n + ' из ' + total, pctS: Math.round(n / total * 1000) / 10, aboutN: 'Выполнено ' + n + ' из ' + total,
      rows, next, hasEv: ev.length > 0, ev,
      celOn: cel > 0, celCls: 'nb__cel--' + cel, blockCls: cel === 3 ? 'nb--out' : '', blockAria: cel > 0 ? 'true' : 'false',
      hasToast: !!S.toast, toast: S.toast
    };
  }
}
